import { SeedOauthPkceClient } from "../../src/Client";
import { mockServerPool } from "../mock-server/MockServerPool";

describe("OauthClient", () => {
    test("authorize", async () => {
        const server = mockServerPool.createServer();
        const client = new SeedOauthPkceClient({ maxRetries: 0, environment: server.baseUrl });

        const rawResponseBody = { code: "auth_code_xyz", state: "xyz" };

        server.mockEndpoint().get("/oauth/authorize").respondWith().statusCode(200).jsonBody(rawResponseBody).build();

        const response = await client.oauth.authorize({
            response_type: "code",
            client_id: "client_abc123",
            redirect_uri: "https://example.com/callback",
            code_challenge: "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM",
            code_challenge_method: "S256",
            scope: "read write",
            state: "xyz",
        });
        expect(response).toEqual(rawResponseBody);
    });
});
